export const VOICE_TRACKS: Record<string, { zh?: VoiceTrack }> = {
  "c112-ceiling": { zh: { audio: media("tts/cave-112/spot-c112-ceiling.zh.mp3"), cues: [{"text":"抬头看窟顶。","start":0.05,"dur":1.805},{"text":"这一口藻井井心是四云头团花：四朵云头向中心收拢，托起中央一朵团花，简洁而饱满。","start":1.855,"dur":9.171},{"text":"覆斗顶四面向中心收拢，形似一座华盖，象征佛说法时头顶的宝盖。","start":11.026,"dur":6.974},{"text":"四披则画千佛，中央各画趺坐佛一身。","start":18,"dur":4.395},{"text":"请注意一个细节：四披的千佛排列方式与四壁的经变完全不同——上面是秩序，下面是叙事，眼睛在两者之间移动时会自然产生\"内外\"的层次感。","start":22.395,"dur":14.158}] } },
  "c112-pipa": { zh: { audio: media("tts/mural-pipa/guide.zh.mp3"), cues: [{"text":"请看画面中央这位舞伎。","start":0.05,"dur":2.713},{"text":"她把琵琶甩到背后，反腕去拨，同时一足蹬地、一足踢起，身体拧成一个优美的\"三道弯\"。","start":2.763,"dur":8.605},{"text":"请特别注意她的线条：这是盛唐一路传下来的\"兰叶描\"，一根线有粗有细、有起有伏，像兰叶在风中翻转，把丝绸的飘动和身体的柔软一次画尽。","start":11.368,"dur":14.079},{"text":"再看颜色：朱砂的红、石青的蓝、石绿的绿，再加一层薄薄的金箔。","start":25.447,"dur":7.039},{"text":"一千二百年过去了，红还在烧，蓝还在亮。","start":32.487,"dur":4.382},{"text":"左右两侧不是点缀，而是一支编制完整的乐队：排箫、笙、阮、鼓、拍板，十几种乐器同时发声。","start":36.868,"dur":10.145},{"text":"这些图像是研究唐代音乐最直接的材料——很多乐器在实物上早已失传，却在这些壁画里保存了演奏的姿势、持琴的角度、手指的位置。","start":47.013,"dur":13.171},{"text":"所以有人说，敦煌壁画是一座\"会发声的博物馆\"。","start":60.184,"dur":5.066}] } },
  "c112-west": { zh: { audio: media("tts/cave-112/spot-c112-west.zh.mp3"), cues: [{"text":"正前方西壁开一个盝顶帐形龛——您可以把龛形理解成一顶帐子，佛坐在里面，龛顶饰棋格团花图案及佛、菩萨像。","start":0.05,"dur":11.279},{"text":"龛下是马蹄形佛床，唐塑一铺佛、菩萨、弟子五身像；佛床之下还有壸门，门内画着伎乐。","start":11.329,"dur":9.474},{"text":"请留意这个布局的用意：从窟门进来，先看到壁画上的乐舞，再看到龛内真实的塑像，最后看到佛床下小小的伎乐——图像、雕塑与建筑被串成了一条连续的观看动线。","start":20.803,"dur":15.829}] } },
  "c17-discovery": { zh: { audio: media("tts/cave-17/spot-c17-discovery.zh.mp3"), cues: [{"text":"请环视这个小小的空间。","start":0.05,"dur":2.555},{"text":"按照记载，这里当年堆满了文书，几乎顶到窟顶。","start":2.605,"dur":5},{"text":"现在学者们大多认为，这些文献是在十一世纪初为了避战乱而封存的——也有说法认为这里堆放的是废弃纸张。","start":7.605,"dur":10.763},{"text":"有意思的是，那些被当时人视为\"废纸\"的东西，包含了借贷契约、离婚协议、学童练字的涂鸦、寺院账本、甚至药方和食谱。","start":18.368,"dur":12.105},{"text":"正是这些\"不重要的纸\"，让我们第一次看见了普通唐人的生活：他们借钱、离婚、练字、算账、看病、吃饭。","start":30.474,"dur":10.789},{"text":"宏大叙事里没有他们，但藏经洞里有。","start":41.263,"dur":3.934}] } },
  "c17-stele": { zh: { audio: media("tts/cave-17/spot-c17-stele.zh.mp3"), cues: [{"text":"正前方西壁嵌着一通石碑，高约一点五米，宽约零点七米，是大中五年也就是公元851年的《洪辩告身碑》。","start":0.05,"dur":10.818},{"text":"碑文分三段：上段刻唐朝敕封洪辩为河西都僧统的诏令，中段记沙州收复的经过，下段是洪辩的告身文书。","start":10.868,"dur":11.368},{"text":"它同时是一份政治档案与一件书法作品。","start":22.237,"dur":4.158},{"text":"请您记住这面墙的意义：这是我们今天能够确认这位僧人真实身份、官职与年代的最直接证据——而这间屋子本来是纪念他的。","start":26.395,"dur":11.697}] } },
  "c17-trees": { zh: { audio: media("tts/mural-library/guide.zh.mp3"), cues: [{"text":"您正站在世界上最小的著名洞窟之一里。","start":0.05,"dur":4.042},{"text":"它不到十平方米，却装下了六万余件文书。","start":4.092,"dur":4.197},{"text":"请注意，这里原本不是书库，而是一间纪念堂——晚唐河西都僧统洪辩的影堂。","start":8.289,"dur":7.592},{"text":"请看北壁：画着一对树。","start":15.882,"dur":2.75},{"text":"西侧树下是一位近侍女，手执杖和巾，树间挂着布囊；东侧树下是一位比丘尼，手持纨扇，树间挂着一只水壶。","start":18.632,"dur":11.868},{"text":"一把杖、一条巾、一个布囊、一把扇、一只水壶——晚唐画师的写实能力在这里不再服务于宗教叙事，它只是安静地描述了两个人如何照料另一个人。","start":30.5,"dur":14.118},{"text":"公元1900年6月22日，道士王圆箓在清理第16窟积沙时，偶然发现了这里的封门。","start":44.618,"dur":9.026},{"text":"里面堆满了四世纪到十一世纪的经卷、绢画、契约、账本和书信。","start":53.645,"dur":6.632},{"text":"有意思的是，那些被当时人视为\"废纸\"的东西——借贷契约、离婚协议、学童练字的涂鸦、寺院账本、药方和食谱——恰恰让我们第一次看见了普通唐人的生活。","start":60.276,"dur":14.895}] } },
  "c217-amitayus": { zh: { audio: media("tts/mural-amitayus/guide.zh.mp3"), cues: [{"text":"请看北壁。","start":0.05,"dur":1.516},{"text":"这铺《观无量寿经变》，被很多人认为是唐代青绿山水在洞窟里的巅峰。","start":1.566,"dur":6.947},{"text":"故事的主角是韦提希夫人：她的儿子阿阇世囚禁了父亲，她在狱中向佛陀请教，佛于是教她\"十六观\"——一观一观地观想净土。","start":8.513,"dur":12.276},{"text":"画师做了一件了不起的事：他把十六观全部画进了层层青绿山水之间。","start":20.789,"dur":6.974},{"text":"山不是背景，而是观想发生的地方。","start":27.763,"dur":3.763},{"text":"请顺着流水看：水从山间泻下，穿过楼阁与莲花。","start":31.526,"dur":5.316},{"text":"净土世界的楼阁，和真实的青绿山峦，共用同一条地平线——天上与人间只隔一池水。","start":36.842,"dur":8.566},{"text":"盛唐的画师在这里证明了一件事：山水画本身，就有足够的力气去讲一个关于来世的故事。","start":45.408,"dur":8.803}] } },
  "c217-ceiling": { zh: { audio: media("tts/cave-217/spot-c217-ceiling.zh.mp3"), cues: [{"text":"抬头看窟顶。","start":0.05,"dur":1.805},{"text":"覆斗顶的井心是一朵团花，卷草与垂幔铺向四披。","start":1.855,"dur":5.447},{"text":"它比四壁的经变简单得多——但正是这种克制，让眼睛在看完满壁青绿之后，有一处可以休息的地方。","start":7.303,"dur":9.75},{"text":"窟顶的留白，是盛唐设计里最安静的一笔。","start":17.053,"dur":4.434}] } },
  "c217-pumen": { zh: { audio: media("tts/cave-217/spot-c217-pumen.zh.mp3"), cues: [{"text":"转过身看东壁。","start":0.05,"dur":1.897},{"text":"通壁绘《法华经·观音普门品》：火难、水难、罗刹难、刀杖难……每一种灾难都是一个独立的山水小景，观世音在每一景中现身相救。","start":1.947,"dur":13.526},{"text":"整面墙就像一本图绘的\"应急手册\"——念诵名号，就能找到对应的那一格。","start":15.474,"dur":6.895},{"text":"请留意画师如何在整壁的大构图中给每一\"难\"留出独立的空间：山与山之间，就是故事与故事之间的呼吸。","start":22.368,"dur":10.211}] } },
  "c220-ceiling": { zh: { audio: media("tts/cave-220/spot-c220-ceiling.zh.mp3"), cues: [{"text":"抬头看窟顶。","start":0.05,"dur":1.805},{"text":"这口藻井是宋代重绘的卷瓣莲花团龙井心，而底层的初唐藻井与千佛至今仍在——剥落处隐隐露出初唐的莲花与团花纹样。","start":1.855,"dur":12.566},{"text":"一层画盖着另一层，第220窟本身就像一本地层书：最深处是贞观十六年的初唐，其上依次是五代、宋代的补绘。","start":14.421,"dur":11.618},{"text":"您抬头看到的，是一千三百年层层叠起来的时间。","start":26.039,"dur":4.882}] } },
  "c220-sukhavati": { zh: { audio: media("tts/cave-220/spot-c220-sukhavati.zh.mp3"), cues: [{"text":"左手边南壁，是根据《佛说阿弥陀经》绘成的西方极乐世界图——莫高窟最早、场面最大的净土变。","start":0.05,"dur":9.397},{"text":"整铺画面分三段：中央是阿弥陀佛说法，楼阁亭台浮于七宝池上；两侧是听法的众生与化生童子。","start":9.447,"dur":10.316},{"text":"请注意画师对\"水\"的处理：池水用一道道细线画出波纹，楼阁的倒影倒映其中。","start":19.763,"dur":7.658},{"text":"盛唐以后无数的净土变，都是从这里出发的。","start":27.421,"dur":4.539}] } },
  "c220-vk": { zh: { audio: media("tts/mural-vimalakirti/guide.zh.mp3"), cues: [{"text":"请看东壁。","start":0.05,"dur":1.503},{"text":"这是《维摩诘经》最著名的一幕：居士维摩诘称病，佛陀派智慧的文殊菩萨去探病，两人展开了一场关于\"不二法门\"的大辩论。","start":1.553,"dur":11.342},{"text":"但真正让这幅画出名的，是文殊这一侧的帝王问疾图——头戴冕旒、身着大裘的帝王，身后跟着按品级排列的群臣，还有深目高鼻的各国王子。","start":12.895,"dur":13.211},{"text":"唐人把贞观年间最熟悉的朝堂仪仗，整个搬进了佛经故事。","start":26.105,"dur":5.987},{"text":"有意思的是：这些初唐杰作，直到1943年才重见天日。","start":32.092,"dur":6.289},{"text":"之前将近一千年里，它们一直被一层宋代壁画盖着。","start":38.382,"dur":5.053},{"text":"剥开表层的那一刻，等于把整个初唐画坛的最高水平，还给了世界。","start":43.434,"dur":6.421}] } },
  "c220-yakshi": { zh: { audio: media("tts/cave-220/spot-c220-yakshi.zh.mp3"), cues: [{"text":"请转向右手边北壁。","start":0.05,"dur":2.437},{"text":"这是根据《药师如来本愿经》绘制的巨型壁画，主题是七身药师佛，身边有日光、月光菩萨。","start":2.487,"dur":8.934},{"text":"请把视线放到画面下部：舞伎在莲花座上起舞，两侧乐队伴奏——这是研究唐代乐舞最珍贵的图像之一。","start":11.421,"dur":10.132},{"text":"当年剥开表层壁画时，人们第一次看到了贞观年间长安城里的流行舞姿与乐器。","start":21.553,"dur":7.895},{"text":"您可以把这面墙当成一座唐代的音乐厅：画上的每件乐器、每个舞姿，都是实物与文献之外唯一的现场。","start":29.447,"dur":9.947}] } },
  "c249-ceiling": { zh: { audio: media("tts/cave-249/spot-c249-ceiling.zh.mp3"), cues: [{"text":"现在请抬头，慢慢转动——这是莫高窟最特别的一片穹顶。","start":0.05,"dur":5.726},{"text":"南披画西王母乘凤车，有仙人骑凤前导；北披画东王公乘龙车，四龙拉车、羽人随行；西披正中是阿修罗王，四目四臂，立于海水中，上两手分别托着日月，头顶是须弥山与忉利天宫。","start":5.776,"dur":18.803},{"text":"东披则是莲花摩尼宝珠，两侧伏羲与女娲人首蛇身相对，下面还有雷公击鼓、飞廉奔跑、朱雀与羽人往来。","start":24.579,"dur":11},{"text":"请注意这意味着什么：佛教从印度来，却没有把这片土地原有的天空抹掉。","start":35.579,"dur":7.145},{"text":"印度来的飞天，和汉地的西王母、东王公、伏羲女娲，同住在一个穹顶之下。","start":42.724,"dur":7.513},{"text":"画师用云气把它们缝在了一起——这就是敦煌最动人的地方：它不是某一种文明的独白，而是一场持续千年的对话。","start":50.237,"dur":10.697}] } },
  "c249-sutra": { zh: { audio: media("tts/cave-249/spot-c249-sutra.zh.mp3"), cues: [{"text":"请看向右手边北壁。","start":0.05,"dur":2.371},{"text":"这一壁分上中下三段：最上是天宫伎乐二十身，中部正中画说法图一铺——佛两侧上方各绘两身飞天，下方各绘两身菩萨；其余壁面以千佛填满。","start":2.421,"dur":14.987},{"text":"千佛不是重复劳动，而是一种宗教观念的形象化：它们排成一眼望不到头的行列，让信众感受到时间的长度。","start":17.408,"dur":10.461},{"text":"而在这片秩序里，画师悄悄留出几个位置给飞天——秩序中出现一点动，整面墙就活了。","start":27.868,"dur":8.605}] } },
  "c249-xwm": { zh: { audio: media("tts/mural-xiwangmu/guide.zh.mp3"), cues: [{"text":"第249窟讲的不是一部经，而是一整个天空。","start":0.05,"dur":4.963},{"text":"壁面上缘，乐伎从栏墙后探出半身，吹排箫、弹琵琶、击腰鼓——栏墙与垂幔连成一条水平线，把整面墙变成天界的阳台。","start":5.013,"dur":12.829},{"text":"抬头看窟顶四披，那里是汉地神话的世界：西王母乘凤车，东王公乘龙车，阿修罗王四目四臂托着日月，雷公击鼓，飞廉奔驰，羽人朱雀往来其间。","start":17.842,"dur":15.053},{"text":"请注意一件事：佛教从印度来，却没有把这片土地原有的天空抹掉。","start":32.895,"dur":6.461},{"text":"印度来的飞天，和汉地的西王母、伏羲女娲，同住在一个穹顶之下。","start":39.355,"dur":6.605},{"text":"画师用云气把她们缝在了一起。","start":45.961,"dur":3.342},{"text":"这就是敦煌最动人的地方——它不是某一种文明的独白，而是一场持续千年的对话。","start":49.303,"dur":7.697}] } },
  "c254-ceiling": { zh: { audio: media("tts/cave-254/spot-c254-ceiling.zh.mp3"), cues: [{"text":"抬头看窟顶。","start":0.05,"dur":1.805},{"text":"前部是人字披，东西两披浮塑出十六条凸起的椽子，椽与椽之间画着手持莲花的天人与忍冬；后部转为平棋顶，斗四套叠的方格中央画莲花，四个叉角画飞天、忍冬或火焰。","start":1.855,"dur":17.25},{"text":"这些斗拱与椽子其实是木构建筑的\"备份\"——砂砾岩无法雕刻，工匠便用泥塑把它一笔一笔做了出来。","start":19.105,"dur":9.132}] } },
  "c254-sibi": { zh: { audio: media("tts/cave-254/spot-c254-sibi.zh.mp3"), cues: [{"text":"请转向右手边，北壁。","start":0.05,"dur":2.739},{"text":"这里画的是《尸毗王割肉贸鸽》。","start":2.789,"dur":3.224},{"text":"帝释天为了试探尸毗王的慈悲，让毗首羯摩变成鹰、自己变成鸽子。","start":6.013,"dur":6.882},{"text":"鸽子逃到王腋下求救，鹰却追来索食。","start":12.895,"dur":3.987},{"text":"王说：我不忍伤鸽，也不愿鹰饿死——于是割下自己的肉，放在秤上，要与鸽等重。","start":16.882,"dur":8.039},{"text":"肉割尽了，仍不够重，王便举身坐上秤盘。","start":24.921,"dur":4.684},{"text":"请看他坐上去的那一刻：天平终于平了。","start":29.605,"dur":4.013},{"text":"北魏画师把整个身体重量都压在这个动作上，人物的轮廓被画得极其镇定，反而是周围旁观的人在捶胸痛哭。","start":33.618,"dur":10.934},{"text":"这是北魏式的慈悲：不做姿态，只上秤。","start":44.553,"dur":4.25}] } },
  "c254-tigress": { zh: { audio: media("tts/mural-tigress/guide.zh.mp3"), cues: [{"text":"这是北魏壁画里最震撼的一幅，也是最难直视的一幅。","start":0.05,"dur":5.345},{"text":"摩诃萨埵太子在山中见到一只饿了七天的母虎，它已经要吃掉自己的幼崽。","start":5.395,"dur":7.184},{"text":"太子支开两位兄长，割开自己的喉咙，从崖上跳了下去。","start":12.579,"dur":5.605},{"text":"请您注意画师的构图：他没有把故事切成七格，而是把刺颈、投崖、饲虎、父母哭尸、起塔供养全部压进同一个画面——这叫\"异时同图\"。","start":18.184,"dur":13.25},{"text":"您的视线每一次移开，都会被中央那团最深的墨色拉回虎群。","start":31.434,"dur":5.895},{"text":"这就是北魏画师最了不起的地方：他们用构图代替了时间。","start":37.329,"dur":5.592}] } },
  "c254-whitebuddha": { zh: { audio: media("tts/cave-254/spot-c254-whitebuddha.zh.mp3"), cues: [{"text":"正前方是西壁。","start":0.05,"dur":1.911},{"text":"请您看千佛中央这一铺：佛着白色通肩袈裟，作说法印，两侧各立一菩萨。","start":1.961,"dur":7.816},{"text":"这是第254窟保存最完好、也最特别的一幅——北魏壁画里的佛像大多是红色的、赭色的，唯独这一身是白衣。","start":9.776,"dur":11.289},{"text":"白在北魏的画法里极难：它不靠颜料覆盖，而靠\"留白\"与极薄的白色晕染，稍有失误就前功尽弃。","start":21.066,"dur":9.789},{"text":"请再注意佛的面部：凹凸晕染的痕迹依然清晰，鼻梁、眼窝、下颌都有一层渐变的暖白——这正是西域传来的\"天竺遗法\"。","start":30.855,"dur":11.553}] } },
  "c257-ceiling": { zh: { audio: media("tts/cave-257/spot-c257-ceiling.zh.mp3"), cues: [{"text":"请抬头。","start":0.05,"dur":1.345},{"text":"这道像屋顶一样从脊线向两侧倾斜的结构叫\"人字披\"。","start":1.395,"dur":5.224},{"text":"莫高窟开凿在砂砾岩崖壁上，石质松散无法雕刻，所以工匠用泥塑与彩绘，把中原木构建筑的屋顶\"搬\"进了洞窟：椽子、斗拱、瓦垄一样不少。","start":6.618,"dur":14.184},{"text":"椽与椽之间画着连绵的忍冬纹——那种像藤蔓一样卷曲、生生不息的纹样。","start":20.803,"dur":7.026},{"text":"窟顶后部则转为\"平棋顶\"，方格层层套叠，格心画莲花，叉角画飞天与火焰。","start":27.829,"dur":8.145},{"text":"抬头三十秒，您看到的就是一部立体的中国建筑史。","start":35.974,"dur":5.158}] } },
  "c257-deer": { zh: { audio: media("tts/mural-deer/guide.zh.mp3"), cues: [{"text":"请看这面西壁。","start":0.05,"dur":1.858},{"text":"它用一条横卷，讲完了整部《九色鹿经》。","start":1.908,"dur":3.697},{"text":"故事从两端同时开始：左边，九色鹿跃入恒河救起溺水者调达；右边，王后梦见九色神鹿，想要它的皮做褥、角做饰，国王于是以半壁江山悬赏。","start":5.605,"dur":14.868},{"text":"两条线在画面中央相撞——神鹿被围，却昂首走到国王面前，从容陈情。","start":20.474,"dur":7.763},{"text":"国王最终下令：举国保护此鹿。","start":28.237,"dur":3.553},{"text":"请您留意画面的骨架：赭红色的底壁，铁线描的轮廓，石青与石绿在氧化之后变成了沉静的青褐。","start":31.789,"dur":9.605},{"text":"而画师把宫殿屋顶当作\"分镜线\"，让宫室与山林同处一幅——这种手法比电影蒙太奇早了将近一千年。","start":41.395,"dur":10.171}] } },
  "c257-pillar": { zh: { audio: media("tts/cave-257/spot-c257-pillar.zh.mp3"), cues: [{"text":"在您身旁这座方形塔柱，是北魏洞窟最典型的空间装置。","start":0.05,"dur":5.568},{"text":"它连接窟顶与地面，每一面都开龛，龛内塑佛像，龛外画供养菩萨与飞天。","start":5.618,"dur":7.553},{"text":"信众入窟后要绕着它右旋行走，边走边观想——所以这类洞窟不是让人\"看\"的，而是让人\"走\"的。","start":13.171,"dur":9.289},{"text":"整座窟就是一个可以穿行的仪式空间。","start":22.461,"dur":3.803},{"text":"您现在的位置在塔柱东向面，请按住拖动，绕到它的背面去看看。","start":26.263,"dur":6.645}] } },
  "c257-south": { zh: { audio: media("tts/cave-257/spot-c257-south.zh.mp3"), cues: [{"text":"请转向您的左手边，这是南壁。","start":0.05,"dur":3.318},{"text":"上半部画天宫伎乐，中部画千佛，而值得您停下来看的是下方那条故事带：《沙弥守戒自杀因缘》。","start":3.368,"dur":9.961},{"text":"一个年轻沙弥奉命去长者家乞食，开门的少女心生爱慕，沙弥为守戒律自刎而死。","start":13.329,"dur":8.5},{"text":"故事分七个情节，自东向西依次展开——受命、乞食、开门、守戒、陈情、交罚金、火化起塔。","start":21.829,"dur":10.105},{"text":"它其实是北魏的\"戒律教科书\"，用最极端的故事告诉僧人：戒不可破。","start":31.934,"dur":6.539},{"text":"旁边的《弊狗因缘》讲一条恶狗因善待比丘而转世为僧，因果报应，一目了然。","start":38.474,"dur":7.697}] } },
  "c285-bandits": { zh: { audio: media("tts/mural-bandits/guide.zh.mp3"), cues: [{"text":"请把目光沿着这面南壁从左向右走一遍。","start":0.05,"dur":4.121},{"text":"这是一条被放平的时间线。","start":4.171,"dur":2.816},{"text":"左边，五百人造反，与官军激战被俘；接着，国王下令剜去他们的双眼，把他们赶进深山；中段，盲人在山峦之间哀号——请留意这些青绿的山，它们把人物一圈一圈围住，在这里山不是风景，而是囚禁。","start":6.987,"dur":19.553},{"text":"最右边，佛陀现身说法，五百人合掌跪坐。","start":26.539,"dur":4.763},{"text":"有趣的是，画师没有画出眼睛复明的那一瞬间，他只画了听完之后的安静。","start":31.303,"dur":7.197},{"text":"奇迹被留在了画外。","start":38.5,"dur":2.25},{"text":"这个洞窟还有一个特别之处：它是莫高窟少数有确切纪年的洞窟之一，西魏大统四到五年，也就是公元538到539年。","start":40.75,"dur":12.671},{"text":"您看到的这些山峦、树木、房舍，构成了一套完整的叙事节奏：人物走过一片山，故事就往前走一步。","start":53.421,"dur":9.632}] } },
  "c285-ceiling": { zh: { audio: media("tts/cave-285/spot-c285-ceiling.zh.mp3"), cues: [{"text":"抬头看四披。","start":0.05,"dur":1.845},{"text":"东披画伏羲女娲，人首蛇身，相对而立，中间共举一颗莲花摩尼宝珠，两侧还有飞廉、飞天与十三首的瑞兽；南披画朱雀、九首瑞兽与羽人；北披画十一首瑞兽与乌获。","start":1.895,"dur":17.342},{"text":"请再往下看披脚：一排小小的禅僧正坐在山间石窟里打坐——这是\"山居禅僧\"的图像，几乎每一位都坐在一个尖顶的小龛中。","start":19.237,"dur":11.711},{"text":"这些禅僧像其实把这整座洞窟的用途说了出来：第285窟主室两侧还开有四个小禅窟，僧人在其中观像、禅修。","start":30.947,"dur":11.197},{"text":"也就是说，这里不只是一个可以参观的礼拜空间，更是一个可以住进去修行的场所。","start":42.145,"dur":7.789}] } },
  "c285-west": { zh: { audio: media("tts/cave-285/spot-c285-west.zh.mp3"), cues: [{"text":"正前方西壁中央凿一圆券形大龛，两侧各有一小龛。","start":0.05,"dur":5.621},{"text":"龛内的塑像经历代重修，但龛外壁面上的护法诸神仍是西魏原笔：龛外南侧上部与窟顶连接处，画着一个白色圆轮与六个白色椭圆轮——这是西魏人对日月星辰的想象。","start":5.671,"dur":16.25},{"text":"这类\"天文图像\"在佛教洞窟里出现得很早，说明此时的敦煌，佛、道、汉地神话与天文知识仍然混融在同一套宇宙观里。","start":21.921,"dur":12.276}] } },
  "c3-almsgiving": { zh: { audio: media("tts/cave-3/spot-c3-almsgiving.zh.mp3"), cues: [{"text":"转身看东壁。","start":0.05,"dur":1.753},{"text":"门上画五身趺坐佛，门北绘散财观音——象牙、金钱、宝珠从观音手中流泻而下，下方一贫儿捧盘承接，这叫\"七宝施贫\"。","start":1.803,"dur":12.25},{"text":"元代画师在这里画出了整座洞窟最温柔的瞬间：千手千眼不是为了威严，而是为了能同时接住每一个需要帮助的人。","start":14.053,"dur":11.118}] } },
  "c3-north": { zh: { audio: media("tts/cave-3/spot-c3-north.zh.mp3"), cues: [{"text":"转过身看北壁。","start":0.05,"dur":1.924},{"text":"这里还有一铺十一面千手千眼观音，十一面作5、5、1排列，与南壁的3、7、1正好不同。","start":1.974,"dur":9.658},{"text":"两铺观音相对而立，把整座洞窟变成了一条被千手环抱的甬道。","start":11.632,"dur":6.329},{"text":"请在两面之间慢慢移动视线——画师的线描功力，就在这两套\"一千只手\"的细微差别里。","start":17.961,"dur":8.342}] } },
  "c3-sahasra": { zh: { audio: media("tts/mural-sahasrabhuja/guide.zh.mp3"), cues: [{"text":"这座小窟是莫高窟保存最完好的元代洞窟，而它的全部力量来自一种几乎失传的本事：白描。","start":0.05,"dur":9.095},{"text":"请看南壁这身十一面千手千眼观音。","start":9.145,"dur":3.987},{"text":"十一张脸，自下而上按三、七、一排列，最上面是佛面。","start":13.132,"dur":6.421},{"text":"身后，一千只手一圈一圈地展开，像光轮一样托在肩后，每一只掌心里都有一只眼睛。","start":19.553,"dur":8.487},{"text":"请您放大画面——每一只手的手指，都是画师一笔一笔完整勾出来的。","start":28.039,"dur":6.211},{"text":"整铺像几乎不用重彩：脸和手用最细的淡墨，衣纹用中锋长线，身后的光轮用铁线描层层展开。","start":34.25,"dur":9.947},{"text":"没有大块颜色干扰，线的疏密本身，就成了光。","start":44.197,"dur":4.684},{"text":"这是白描与壁画在敦煌的最后一次伟大合作。","start":48.882,"dur":4.408}] } },
  "c320-apsara": { zh: { audio: media("tts/mural-apsara/guide.zh.mp3"), cues: [{"text":"这四身飞天，被公认为盛唐最美的一屏。","start":0.05,"dur":4.424},{"text":"她们两两成对，相对而舞，一手散花，一手托着花盘。","start":4.474,"dur":5.632},{"text":"请您注意两件事。","start":10.105,"dur":2.079},{"text":"第一，她们的飞不靠翅膀——靠的是身体的反转和飘带的走向。","start":12.184,"dur":6.197},{"text":"第二，四身飞天的飘带方向几乎一致，弧度彼此呼应。","start":18.382,"dur":5.697},{"text":"画师从来没有画过风，他只画了被风吹动的东西，而您的大脑自动补上了风。","start":24.079,"dur":7.461},{"text":"这就是盛唐画师的本事：他们不满足于画出神，他们要画出速度和空气。","start":31.539,"dur":6.882},{"text":"线条用的是\"兰叶描\"，一根线有粗有细、有起有伏，像兰叶在风中翻转，丝绸的柔软和风的流动被一次画尽。","start":38.421,"dur":10.763}] } },
  "c320-ceiling": { zh: { audio: media("tts/cave-320/spot-c320-ceiling.zh.mp3"), cues: [{"text":"抬头看窟顶。","start":0.05,"dur":1.805},{"text":"藻井井心是一朵云头牡丹，周围一圈圈边饰：方胜纹、半团花、菱形纹、团花、鳞纹，最外一层是垂角铃幔帷。","start":1.855,"dur":11.645},{"text":"朱、青、绿三色叠韵交替，色彩浓艳厚重，保存得极好。","start":13.5,"dur":6.289},{"text":"请留意一个细节：边饰的每一层都不一样，但它们的\"节奏\"是统一的——就像一首曲子换了乐器，节拍不变。","start":19.789,"dur":9.474},{"text":"盛唐的装饰设计，靠的不是繁复，而是节奏。","start":29.263,"dur":4.724}] } },
  "c320-sutra": { zh: { audio: media("tts/cave-320/spot-c320-sutra.zh.mp3"), cues: [{"text":"请转向右手边北壁。","start":0.05,"dur":2.437},{"text":"这里是一铺完整的《观无量寿经变》：中间是极乐世界的净土场面，东侧画\"未生怨\"——阿阇世王子囚禁父王的故事；西侧画\"十六观\"——韦提希夫人在狱中依佛所教，一观一观地观想。","start":2.487,"dur":17.013},{"text":"所以一整面墙其实同时在讲三件事：净土是什么样子、为什么要往生、以及具体怎么修。","start":19.5,"dur":8.961},{"text":"经变不是装饰画，它是一部可以\"读\"的图文教科书。","start":28.461,"dur":4.737}] } },
  "c323-ceiling": { zh: { audio: media("tts/cave-323/spot-c323-ceiling.zh.mp3"), cues: [{"text":"抬头看窟顶。","start":0.05,"dur":1.805},{"text":"井心是一朵团花，四披垂幔之下铺满千佛。","start":1.855,"dur":4.882},{"text":"注意上下的对比：四壁讲历史与传说，窟顶只讲秩序。","start":6.737,"dur":5.697},{"text":"千佛一行行排列，像织物的经纬，把一切故事都收拢在一个安静的网格之下。","start":12.434,"dur":7.605}] } },
  "c323-south": { zh: { audio: media("tts/cave-323/spot-c323-south.zh.mp3"), cues: [{"text":"请转向左手边南壁。","start":0.05,"dur":2.476},{"text":"这里画的是江南的感应故事：西晋吴淞江石佛浮江、东晋扬都出金像。","start":2.526,"dur":7.079},{"text":"传说中，佛像不从西域来，而是从江水里\"浮\"出来——佛教进入江南，就这样被画成了一次次水上的奇迹。","start":9.605,"dur":9.829},{"text":"请注意山水在其中的作用：江水把情节一格格隔开，人物乘船、岸上礼拜，山与水共同完成了叙事。","start":19.434,"dur":10.263}] } },
  "c323-zhangqian": { zh: { audio: media("tts/mural-zhangqian/guide.zh.mp3"), cues: [{"text":"请看北壁中部这一条长卷。","start":0.05,"dur":2.845},{"text":"这是敦煌独有的题材：佛教\"史迹画\"。","start":2.895,"dur":3.816},{"text":"第一景是汉武帝在甘泉宫礼拜一尊金人——传说那金人来自匈奴的祭天之所，唐人相信，这就是佛像进入中国的起点。","start":6.711,"dur":11.263},{"text":"第二景，武帝派遣张骞持节出使西域，去求取佛法。","start":17.974,"dur":5.513},{"text":"请注意这里做了什么：史实上，张骞出使在公元前二世纪，佛教传入还要再晚两百年。","start":23.487,"dur":8.803},{"text":"但初唐的画师不管这些。","start":32.289,"dur":2.882},{"text":"他们需要一条更有力的叙事：金人先来，佛法随之而至，而这条路上站着的正是敦煌。","start":35.171,"dur":8.355},{"text":"历史被重写，是为了给信仰一条来路。","start":43.526,"dur":4.224},{"text":"其余各景，是石佛浮江、金像出渚这些江南感应故事。","start":47.75,"dur":5.895},{"text":"山峦把一桩桩\"史迹\"隔成格子，人物在山水之间行走、渡河——这是敦煌壁画里最早的历史叙事，几乎就是一部初唐的连环画。","start":53.645,"dur":12.171}] } },
  "c329-amitabha": { zh: { audio: media("tts/cave-329/spot-c329-amitabha.zh.mp3"), cues: [{"text":"请把视线放下来，转向左手边南壁。","start":0.05,"dur":3.845},{"text":"这是一铺阿弥陀经变：净土世界以绿水池潭和楼阁亭台来表现，楼阁之间有飞天往来。","start":3.895,"dur":9.158},{"text":"请留意水的画法——池水碧绿，水波用细线勾出，倒影清清楚楚。","start":13.053,"dur":6.605},{"text":"初唐画师画净土，画的其实是他们见过的最好的园林。","start":19.658,"dur":5.25}] } },
  "c329-caisson": { zh: { audio: media("tts/mural-lotusapsara/guide.zh.mp3"), cues: [{"text":"请抬头，看这口初唐的莲花飞天藻井。","start":0.05,"dur":4.082},{"text":"井心是一朵大团花，花心呈五色法轮状，花瓣顺着同一个方向旋转。","start":4.132,"dur":7.118},{"text":"花的外圈，四身持花飞天在湛蓝的天空中同向飞行，蓝云环绕。","start":11.25,"dur":6.868},{"text":"请留意她们的衣带：方向和云的流向完全一致，中心法轮的花瓣也顺着同一方向——所有元素被组织进同一个漩涡。","start":18.118,"dur":10.737},{"text":"当你站定仰望，方井一层层收拢，视线最终落进这个漩涡，然后被带着一起转。","start":28.855,"dur":7.829},{"text":"没有屏幕，没有音响，只有线条的方向和颜色的节奏。","start":36.684,"dur":5.566},{"text":"一千三百年前的画师，就已经会做沉浸式设计了。","start":42.25,"dur":4.697}] } },
  "c329-maitreya": { zh: { audio: media("tts/cave-329/spot-c329-maitreya.zh.mp3"), cues: [{"text":"转身看北壁，这里画的是弥勒经变：水池和楼阁亭台之间，尽是七宝庄严。","start":0.05,"dur":7.766},{"text":"弥勒净土的特点是\"未来\"——经中说，弥勒下生成佛时，人寿八万四千岁，庄稼一种七收。","start":7.816,"dur":9.25},{"text":"画师把这些细节全画了出来：田地里庄稼茂盛，路不拾遗。","start":17.066,"dur":6.013},{"text":"这不是一张风景，而是一份关于未来的承诺。","start":23.079,"dur":4.382}] } },
  "c420-fahua": { zh: { audio: media("tts/cave-420/spot-c420-fahua.zh.mp3"), cues: [{"text":"请把视线从三兔移向西披与南披。","start":0.05,"dur":3.687},{"text":"这里画的是《法华经·观世音菩萨普门品》：火难、水难、罗刹难、刀杖难、牢狱难、盗贼难……一格一难，观世音在每一格中现身相救。","start":3.737,"dur":13.921},{"text":"您可以把它理解成一份用图绘成的\"应急清单\"——只要念诵名号，任何困境都有对应的救援画面。","start":17.658,"dur":8.882},{"text":"南披则转向《譬喻品》：曲尺形的院墙、殿堂、重阁回廊错落相间，那是著名的\"火宅\"与\"化城\"比喻，整座建筑群正在燃烧，而孩子们还在里面游戏。","start":26.539,"dur":14.882},{"text":"隋代画师用建筑的纵深，把一部抽象的经变画成了一座可以走进去的房子。","start":41.421,"dur":7.211}] } },
  "c420-hares": { zh: { audio: media("tts/mural-threehares/guide.zh.mp3"), cues: [{"text":"请抬头看窟顶正中的藻井。","start":0.05,"dur":2.95},{"text":"三只兔子正在互相追逐，首尾相接，围成一个环。","start":3,"dur":5.461},{"text":"奇怪的是：每只兔子看起来都有两只耳朵，可整幅画上一共只画了三只耳朵——它们两两共用。","start":8.461,"dur":9.145},{"text":"这在一千五百年前是一个极高级的图形智慧，叫做\"共用形\"。","start":17.605,"dur":5.776},{"text":"更奇妙的是，同样的图案也出现在中亚的金属器、伊朗的瓷砖、欧洲中世纪教堂的彩窗上。","start":23.382,"dur":9.105},{"text":"一条丝绸之路，把这个图形从敦煌带向了整个世界。","start":32.487,"dur":5.5},{"text":"它究竟代表什么？","start":37.987,"dur":2},{"text":"三世轮回？","start":39.987,"dur":1.632},{"text":"日月运行？","start":41.618,"dur":1.632},{"text":"还是单纯的\"无穷\"？","start":43.25,"dur":2.105},{"text":"至今没有定论。","start":45.355,"dur":1.855},{"text":"再把目光移到井心四周的边框：忍冬卷草、狮子与联珠纹一圈一圈向中心收拢，每一层纹样不同，节奏却完全统一——像同一首曲子换了乐器。","start":47.211,"dur":13.763}] } },
  "c420-nirvana": { zh: { audio: media("tts/cave-420/spot-c420-nirvana.zh.mp3"), cues: [{"text":"转向另一侧。","start":0.05,"dur":1.674},{"text":"北披画面的中心是一大幅佛涅槃的场景，以此为中心，左侧分上中下三层，绘有共八幅佛说法图；西披大致分三层横幅，每层都画有数幅说法图，总共达二十三幅之多——这是隋代经变画的一次\"密集展示\"。","start":1.724,"dur":19.947},{"text":"请留意画师解决困难的方法：画面被切得如此之碎，他却用统一的青绿色调与连续的山峦把它们串起来，让观众的眼睛不至于散掉。","start":21.671,"dur":12.789}] } },
  "c420-walls": { zh: { audio: media("tts/cave-420/spot-c420-walls.zh.mp3"), cues: [{"text":"最后请看四壁。","start":0.05,"dur":2.029},{"text":"中央开一方形浅龛，龛内塑趺坐佛一身、胁侍菩萨二身，佛袈裟下摆上还能看到数个\"卍\"字符号；龛顶绘飞天二身、火焰忍冬佛光，佛座两侧各绘一狮子。","start":2.079,"dur":15.461},{"text":"龛的四周被千佛填满，一格一格，像织物的经纬。","start":17.539,"dur":5.421},{"text":"整座洞窟的布局非常清楚：下面是给眼睛看的佛国，上面是给时间看的经变，最上面是给宇宙看的三只兔子。","start":22.961,"dur":10.75}] } },
  "c57-beauty": { zh: { audio: media("tts/mural-beauty/guide.zh.mp3"), cues: [{"text":"这个洞窟被称为\"美人窟\"，全部原因就在这面南壁上。","start":0.05,"dur":5.358},{"text":"请您先看中央的观世音菩萨：面容丰润，眉线细长，朱唇微微开启，仿佛下一秒就要开口说话。","start":5.408,"dur":9.526},{"text":"再看她的头冠——那不是画上去的金色，而是真的金属。","start":14.934,"dur":5.329},{"text":"工匠先用调了胶的泥浆在壁上一点点堆出花瓣和珠串的立体纹样，干透以后刷胶，再贴上捶打得极薄的金箔，这叫\"沥粉贴金\"。","start":20.263,"dur":11.921},{"text":"所以无论您从哪个角度看，只要有一点光，冠上的珠串就会闪。","start":32.184,"dur":6.184},{"text":"一千四百年过去了，它还在闪。","start":38.368,"dur":3.329},{"text":"往下看，是一列供养人：都督夫人太原王氏，后面跟着女儿和侍女，十几个人。","start":41.697,"dur":7.934},{"text":"脸上厚厚的白粉，两颊胭脂，细长的桂叶眉，嘴唇只点中间一点朱红。","start":49.632,"dur":7.25},{"text":"这幅画其实是一份用画笔保存下来的初唐时尚档案。","start":56.882,"dur":5.145}] } },
  "c57-ceiling": { zh: { audio: media("tts/cave-57/spot-c57-ceiling.zh.mp3"), cues: [{"text":"抬头看窟顶。","start":0.05,"dur":1.805},{"text":"这口藻井的井心画着两条龙，环绕中央的莲花相对而立，尾部相交叉。","start":1.855,"dur":6.974},{"text":"方形井心之外是一层圆环联珠纹，再外面是方形二方连续纹——方中有圆，圆外有方，一层层套下去。\"藻\"是水生植物，\"井\"是井口，古人相信在木构建筑最高处画上水草莲花可以厌火。","start":8.829,"dur":18.605},{"text":"于是藻井成了中国建筑里装饰最繁复的一个部位，也是画师留给自己的一份炫技。","start":27.434,"dur":7.882}] } },
  "c57-donors": { zh: { audio: media("tts/cave-57/spot-c57-donors.zh.mp3"), cues: [{"text":"请把视线往下移。","start":0.05,"dur":2.147},{"text":"说法图的下部画着一列供养人，领头的是都督夫人太原王氏，身后依次是女儿与侍女，共十余身。","start":2.197,"dur":9.75},{"text":"请看她们的妆容：脸上敷着厚厚的白粉，两颊晕着胭脂，眉画成细长的\"桂叶眉\"，唇只点中间一点朱红——这是初唐最时髦的贵妇妆。","start":11.947,"dur":12.724},{"text":"再看衣裙：宽大的袖、拖地的裙，颜色一层压一层。","start":24.671,"dur":5.461},{"text":"这幅画其实是一份\"时尚档案\"，比任何文字记载都更直观。","start":30.132,"dur":5.842},{"text":"而它之所以被画在这里，是因为供养人是真实出钱开窟的人——她们用一笔钱，买到了一个在一千四百年后仍被人注视的位置。","start":35.974,"dur":11.737}] } },
  "c61-ceiling": { zh: { audio: media("tts/cave-61/spot-c61-ceiling.zh.mp3"), cues: [{"text":"抬头看窟顶。","start":0.05,"dur":1.805},{"text":"这是敦煌最大的华盖式藻井之一：中心井心画五莲团龙鹦鹉，四周依次铺开联珠纹、回纹、团花、双凤双麒麟纹饰，最外圈是层层垂幔——整个窟顶被画成一顶张开的华盖，仿佛文殊说法时头顶的宝盖。","start":1.855,"dur":20.592},{"text":"注意它的尺度感：正因为洞窟如此之大，这口藻井的每一圈纹饰都被放大到可以被\"仰望\"的尺寸。","start":22.447,"dur":8.947}] } },
  "c61-sutras": { zh: { audio: media("tts/cave-61/spot-c61-sutras.zh.mp3"), cues: [{"text":"请转向右手边北壁。","start":0.05,"dur":2.437},{"text":"上部并排五铺大型经变，自西向东依次是：密严经变、天请问经变、药师经变、华严经变、思益经变。","start":2.487,"dur":10.842},{"text":"一壁五铺，这是敦煌经变画\"饱和\"到极限的样子。","start":13.329,"dur":4.895},{"text":"每一铺都有独立的构图与主尊，但它们共用同一套配色与山水语言，远看是五扇连续的屏风，近看是五部不同的经。","start":18.224,"dur":10.908},{"text":"请慢慢横移视线，感受五代画师如何在一面墙上安排五部经典。","start":29.132,"dur":6.526}] } },
  "c61-vimala": { zh: { audio: media("tts/cave-61/spot-c61-vimala.zh.mp3"), cues: [{"text":"转过身看东壁。","start":0.05,"dur":1.897},{"text":"上段是一铺大型《维摩诘经变》，以\"品\"字形排列：门上方是佛国品，维摩诘与文殊分列两侧。","start":1.947,"dur":9.421},{"text":"它正对着西壁的五台山图——文殊的道场在身后，文殊的化身在面前。","start":11.368,"dur":6.789},{"text":"第61窟的一切，都是围绕这位骑狮子的菩萨安排的。","start":18.158,"dur":5.145}] } },
  "c61-wutai": { zh: { audio: media("tts/mural-wutai/guide.zh.mp3"), cues: [{"text":"请看西壁。","start":0.05,"dur":1.555},{"text":"这是一张十三米长、三米六高的《五台山图》——现存最宏大的地图式山水画。","start":1.605,"dur":7.224},{"text":"五台山是文殊菩萨的道场。","start":8.829,"dur":3.066},{"text":"五代时期，敦煌到中原的路断了，但文殊信仰反而更热。","start":11.895,"dur":5.618},{"text":"曹氏家族凿了这座\"文殊堂\"，然后用整面西壁画下五台山。","start":17.513,"dur":6.053},{"text":"请靠近看：山川用俯瞰的角度，建筑却画成正立面，道路把一座座寺院、城郭、关口串起来，榜题密密麻麻写满地名。","start":23.566,"dur":12.013},{"text":"山路上有挑担的行脚僧、骑马的官员、驼着货物的商队。","start":35.579,"dur":5.684},{"text":"对于没法亲赴五台的敦煌信众，这面墙就是山本身。","start":41.263,"dur":5.447},{"text":"拿到这张画，等于拿到一份十世纪的五台山旅行手册。","start":46.711,"dur":5.184}] } },
  "cave-112-intro": { zh: { audio: media("tts/cave-112/intro.zh.mp3"), cues: [{"text":"这里是第112窟，中唐。","start":0.05,"dur":3.042},{"text":"请您屏住呼吸——左手边南壁《观无量寿经变》里，藏着中国美术史上最著名的一个舞姿：反弹琵琶。","start":3.092,"dur":9.697},{"text":"她把琵琶举到背后，反手拨弦，一足踢起，衣带翻卷。","start":12.789,"dur":5.684},{"text":"有人说这是一个真实存在过的舞姿，也有人说它是画师心中的极致想象。","start":18.474,"dur":7.092},{"text":"点亮光点，我一处处讲给您听。","start":25.566,"dur":3.329}] } },
  "cave-17-intro": { zh: { audio: media("tts/cave-17/intro.zh.mp3"), cues: [{"text":"第17窟，藏经洞。","start":0.05,"dur":2.529},{"text":"这是世界上最小的著名洞窟之一——面积不到十平方米，却装下了六万余件文书。","start":2.579,"dur":7.618},{"text":"请注意，这里原本不是书库，而是晚唐河西都僧统洪辩的影堂，也就是纪念堂。","start":10.197,"dur":7.961},{"text":"公元1900年6月22日，道士王圆箓清理第16窟积沙时偶然发现了一个封闭的耳室。","start":18.158,"dur":8.855},{"text":"那一刻，一门国际性的学问\"敦煌学\"，就此诞生。","start":27.013,"dur":5.079}] } },
  "cave-217-intro": { zh: { audio: media("tts/cave-217/intro.zh.mp3"), cues: [{"text":"欢迎来到第217窟，盛唐。","start":0.05,"dur":3.621},{"text":"这座洞窟藏着唐代青绿山水在洞窟里的巅峰。","start":3.671,"dur":4.921},{"text":"请转向右手边北壁——那铺《观无量寿经变》用石青石绿把山峦、流水、楼阁画成一体；再转身看东壁，那里是《法华经·观音普门品》的诸难救济。","start":8.592,"dur":14.316},{"text":"点亮光点。","start":22.908,"dur":1.632}] } },
  "cave-220-intro": { zh: { audio: media("tts/cave-220/intro.zh.mp3"), cues: [{"text":"欢迎来到第220窟，开凿于贞观十六年——公元642年。","start":0.05,"dur":6.437},{"text":"这是敦煌翟氏家族的\"家窟\"，四壁全是初唐画坛第一流的手笔。","start":6.487,"dur":6.25},{"text":"转过身去，东壁的《维摩诘经变》里有著名的帝王问疾图；右手边北壁是药师七佛与乐舞；左手边南壁，是莫高窟最早、场面最大的净土变。","start":12.737,"dur":13.592},{"text":"请点亮光点。","start":26.329,"dur":1.803}] } },
  "cave-249-intro": { zh: { audio: media("tts/cave-249/intro.zh.mp3"), cues: [{"text":"欢迎来到第249窟，西魏。","start":0.05,"dur":3.542},{"text":"这座洞窟最动人的东西不在四壁，而在您的头顶——请先不要急着抬头。","start":3.592,"dur":6.868},{"text":"您身边四壁的上缘画着一整圈天宫伎乐：乐伎从栏墙后探出半身，吹排箫、弹琵琶、击腰鼓。","start":10.461,"dur":9.829},{"text":"而现在，请慢慢地抬起头来：窟顶四披上不是佛国，而是中国上古神话的天空。","start":20.289,"dur":8.211},{"text":"西王母乘凤车，东王公乘龙车，阿修罗王四目四臂托举日月。","start":28.5,"dur":6.579}] } },
  "cave-254-intro": { zh: { audio: media("tts/cave-254/intro.zh.mp3"), cues: [{"text":"欢迎来到第254窟，北魏。","start":0.05,"dur":3.476},{"text":"请您先深呼吸——这座洞窟里的画，是莫高窟最激烈的一批。","start":3.526,"dur":5.579},{"text":"左手边南壁是《萨埵太子舍身饲虎》，右手边北壁是《尸毗王割肉贸鸽》，正前方西壁千佛中央有一铺保存极好的白衣佛。","start":9.105,"dur":11.513},{"text":"远处的东壁还留着《降魔变》。","start":20.618,"dur":3.079},{"text":"请慢慢转身，再点亮光点，我一处一处讲。","start":23.697,"dur":4.368}] } },
  "cave-257-intro": { zh: { audio: media("tts/cave-257/intro.zh.mp3"), cues: [{"text":"欢迎来到第257窟，北魏。","start":0.05,"dur":3.489},{"text":"您正站在一座中心塔柱窟里——身侧这根方形塔柱，就是整座洞窟的\"心脏\"。","start":3.539,"dur":7.039},{"text":"信众入窟后先绕塔右旋一周，最后才面对西壁。","start":10.579,"dur":5.066},{"text":"请先向前看：西壁中层那条长长的横卷，就是举世闻名的《九色鹿王本生》。","start":15.645,"dur":7.303},{"text":"您可以拖动环视，抬头看人字披顶，或者直接点亮画面中闪光的金色光点，我会一处一处讲给您听。","start":22.947,"dur":9.724}] } },
  "cave-285-intro": { zh: { audio: media("tts/cave-285/intro.zh.mp3"), cues: [{"text":"欢迎来到第285窟，西魏，公元538到539年——这是莫高窟少数有确切纪年的洞窟之一。","start":0.05,"dur":10.345},{"text":"左手边南壁是一条通壁横卷，讲《五百强盗成佛因缘》：造反、被俘、剜眼、放逐、闻法、复明、出家。","start":10.395,"dur":11.132},{"text":"抬头则是伏羲女娲与雷神飞廉。","start":21.526,"dur":3.737},{"text":"请点亮光点。","start":25.263,"dur":1.803}] } },
  "cave-3-intro": { zh: { audio: media("tts/cave-3/intro.zh.mp3"), cues: [{"text":"欢迎来到第3窟——莫高窟保存最完好的元代洞窟，也是最小的一批洞窟之一。","start":0.05,"dur":7.516},{"text":"请转向左手边南壁：一铺十一面千手千眼观音立像。","start":7.566,"dur":5.816},{"text":"这座洞窟的全部力量来自一种几乎失传的本事：白描。","start":13.382,"dur":5.447},{"text":"没有大块浓彩，千手千眼全靠一根根细线画出。","start":18.829,"dur":5.118}] } },
  "cave-320-intro": { zh: { audio: media("tts/cave-320/intro.zh.mp3"), cues: [{"text":"欢迎来到第320窟，盛唐。","start":0.05,"dur":3.424},{"text":"请您转向左手边，然后抬头看南壁的上部——那里有四身散花飞天，被公认为盛唐最美的一屏。","start":3.474,"dur":9.25},{"text":"她们两两成对，相对而舞，一手散花，一手托着花盘。","start":12.724,"dur":5.632},{"text":"请点开光点，我讲给您听她们是怎么\"飞\"起来的。","start":18.355,"dur":4.579}] } },
  "cave-323-intro": { zh: { audio: media("tts/cave-323/intro.zh.mp3"), cues: [{"text":"欢迎来到第323窟，初唐。","start":0.05,"dur":3.608},{"text":"这座洞窟最有名的是\"佛教史迹画\"——敦煌独有的题材。","start":3.658,"dur":5.263},{"text":"请转向右手边北壁：第一景是汉武帝礼拜金人，第二景是张骞出使西域。","start":8.921,"dur":7.513},{"text":"史实上这两件事相隔两百年，但初唐画师把它们画成了同一条因果链。","start":16.434,"dur":7.158},{"text":"点亮光点。","start":23.592,"dur":1.632}] } },
  "cave-329-intro": { zh: { audio: media("tts/cave-329/intro.zh.mp3"), cues: [{"text":"欢迎来到第329窟，初唐。","start":0.05,"dur":3.568},{"text":"这座洞窟最珍贵的东西在您的头顶——请先环视四壁，再慢慢地、用力地抬头。","start":3.618,"dur":7.789},{"text":"窟顶的莲花飞天藻井，四身持花飞天在湛蓝的天空中同向飞行，是初唐藻井里的名作。","start":11.408,"dur":8.947}] } },
  "cave-420-intro": { zh: { audio: media("tts/cave-420/intro.zh.mp3"), cues: [{"text":"欢迎来到第420窟，隋代。","start":0.05,"dur":3.332},{"text":"请您先慢慢抬头，用力地看窟顶正中——那里有三只正在互相追逐的兔子。","start":3.382,"dur":7.066},{"text":"奇怪的是，每只兔子看起来都有两只耳朵，可整幅画上一共只画了三只耳朵。","start":10.447,"dur":7.658},{"text":"这是一个一千五百年前的视觉魔术。","start":18.105,"dur":3.474},{"text":"四披则画满了《法华经》经变。","start":21.579,"dur":3.171},{"text":"点亮光点，我们从兔子说起。","start":24.75,"dur":3.066}] } },
  "cave-57-intro": { zh: { audio: media("tts/cave-57/intro.zh.mp3"), cues: [{"text":"第57窟被称为\"美人窟\"，全部原因就在您左手边的南壁上。","start":0.05,"dur":6.266},{"text":"请走近一些——那一身观世音菩萨面容丰润、眉眼细长、朱唇微启，仿佛下一秒就要开口说话。","start":6.316,"dur":9.421},{"text":"她的头冠是先用泥浆堆出立体纹样、再贴上纯金箔做成的，一千四百年后依然在烛光下闪烁。","start":15.737,"dur":9.197}] } },
  "cave-61-intro": { zh: { audio: media("tts/cave-61/intro.zh.mp3"), cues: [{"text":"欢迎来到第61窟，五代，曹氏归义军时期开凿的\"文殊堂\"。","start":0.05,"dur":6.253},{"text":"请先不要转身，正前方西壁上，是一张十三米长、三米六高的《五台山图》——现存最宏大的地图式山水画。","start":6.303,"dur":10.158},{"text":"五代时敦煌与中原道路阻隔，信徒无法亲赴五台山，于是曹氏家族把整座山画在了墙上。","start":16.461,"dur":9.395},{"text":"点亮光点，我带您在这张地图里走一走。","start":25.855,"dur":4.053}] } },
  "mural-amitayus": { zh: { audio: media("tts/mural-amitayus/guide.zh.mp3"), cues: [{"text":"请看北壁。","start":0.05,"dur":1.516},{"text":"这铺《观无量寿经变》，被很多人认为是唐代青绿山水在洞窟里的巅峰。","start":1.566,"dur":6.947},{"text":"故事的主角是韦提希夫人：她的儿子阿阇世囚禁了父亲，她在狱中向佛陀请教，佛于是教她\"十六观\"——一观一观地观想净土。","start":8.513,"dur":12.276},{"text":"画师做了一件了不起的事：他把十六观全部画进了层层青绿山水之间。","start":20.789,"dur":6.974},{"text":"山不是背景，而是观想发生的地方。","start":27.763,"dur":3.763},{"text":"请顺着流水看：水从山间泻下，穿过楼阁与莲花。","start":31.526,"dur":5.316},{"text":"净土世界的楼阁，和真实的青绿山峦，共用同一条地平线——天上与人间只隔一池水。","start":36.842,"dur":8.566},{"text":"盛唐的画师在这里证明了一件事：山水画本身，就有足够的力气去讲一个关于来世的故事。","start":45.408,"dur":8.803}] } },
  "mural-apsara": { zh: { audio: media("tts/mural-apsara/guide.zh.mp3"), cues: [{"text":"这四身飞天，被公认为盛唐最美的一屏。","start":0.05,"dur":4.424},{"text":"她们两两成对，相对而舞，一手散花，一手托着花盘。","start":4.474,"dur":5.632},{"text":"请您注意两件事。","start":10.105,"dur":2.079},{"text":"第一，她们的飞不靠翅膀——靠的是身体的反转和飘带的走向。","start":12.184,"dur":6.197},{"text":"第二，四身飞天的飘带方向几乎一致，弧度彼此呼应。","start":18.382,"dur":5.697},{"text":"画师从来没有画过风，他只画了被风吹动的东西，而您的大脑自动补上了风。","start":24.079,"dur":7.461},{"text":"这就是盛唐画师的本事：他们不满足于画出神，他们要画出速度和空气。","start":31.539,"dur":6.882},{"text":"线条用的是\"兰叶描\"，一根线有粗有细、有起有伏，像兰叶在风中翻转，丝绸的柔软和风的流动被一次画尽。","start":38.421,"dur":10.763}] } },
  "mural-bandits": { zh: { audio: media("tts/mural-bandits/guide.zh.mp3"), cues: [{"text":"请把目光沿着这面南壁从左向右走一遍。","start":0.05,"dur":4.121},{"text":"这是一条被放平的时间线。","start":4.171,"dur":2.816},{"text":"左边，五百人造反，与官军激战被俘；接着，国王下令剜去他们的双眼，把他们赶进深山；中段，盲人在山峦之间哀号——请留意这些青绿的山，它们把人物一圈一圈围住，在这里山不是风景，而是囚禁。","start":6.987,"dur":19.553},{"text":"最右边，佛陀现身说法，五百人合掌跪坐。","start":26.539,"dur":4.763},{"text":"有趣的是，画师没有画出眼睛复明的那一瞬间，他只画了听完之后的安静。","start":31.303,"dur":7.197},{"text":"奇迹被留在了画外。","start":38.5,"dur":2.25},{"text":"这个洞窟还有一个特别之处：它是莫高窟少数有确切纪年的洞窟之一，西魏大统四到五年，也就是公元538到539年。","start":40.75,"dur":12.671},{"text":"您看到的这些山峦、树木、房舍，构成了一套完整的叙事节奏：人物走过一片山，故事就往前走一步。","start":53.421,"dur":9.632}] } },
  "mural-beauty": { zh: { audio: media("tts/mural-beauty/guide.zh.mp3"), cues: [{"text":"这个洞窟被称为\"美人窟\"，全部原因就在这面南壁上。","start":0.05,"dur":5.358},{"text":"请您先看中央的观世音菩萨：面容丰润，眉线细长，朱唇微微开启，仿佛下一秒就要开口说话。","start":5.408,"dur":9.526},{"text":"再看她的头冠——那不是画上去的金色，而是真的金属。","start":14.934,"dur":5.329},{"text":"工匠先用调了胶的泥浆在壁上一点点堆出花瓣和珠串的立体纹样，干透以后刷胶，再贴上捶打得极薄的金箔，这叫\"沥粉贴金\"。","start":20.263,"dur":11.921},{"text":"所以无论您从哪个角度看，只要有一点光，冠上的珠串就会闪。","start":32.184,"dur":6.184},{"text":"一千四百年过去了，它还在闪。","start":38.368,"dur":3.329},{"text":"往下看，是一列供养人：都督夫人太原王氏，后面跟着女儿和侍女，十几个人。","start":41.697,"dur":7.934},{"text":"脸上厚厚的白粉，两颊胭脂，细长的桂叶眉，嘴唇只点中间一点朱红。","start":49.632,"dur":7.25},{"text":"这幅画其实是一份用画笔保存下来的初唐时尚档案。","start":56.882,"dur":5.145}] } },
  "mural-deer": { zh: { audio: media("tts/mural-deer/guide.zh.mp3"), cues: [{"text":"请看这面西壁。","start":0.05,"dur":1.858},{"text":"它用一条横卷，讲完了整部《九色鹿经》。","start":1.908,"dur":3.697},{"text":"故事从两端同时开始：左边，九色鹿跃入恒河救起溺水者调达；右边，王后梦见九色神鹿，想要它的皮做褥、角做饰，国王于是以半壁江山悬赏。","start":5.605,"dur":14.868},{"text":"两条线在画面中央相撞——神鹿被围，却昂首走到国王面前，从容陈情。","start":20.474,"dur":7.763},{"text":"国王最终下令：举国保护此鹿。","start":28.237,"dur":3.553},{"text":"请您留意画面的骨架：赭红色的底壁，铁线描的轮廓，石青与石绿在氧化之后变成了沉静的青褐。","start":31.789,"dur":9.605},{"text":"而画师把宫殿屋顶当作\"分镜线\"，让宫室与山林同处一幅——这种手法比电影蒙太奇早了将近一千年。","start":41.395,"dur":10.171}] } },
  "mural-library": { zh: { audio: media("tts/mural-library/guide.zh.mp3"), cues: [{"text":"您正站在世界上最小的著名洞窟之一里。","start":0.05,"dur":4.042},{"text":"它不到十平方米，却装下了六万余件文书。","start":4.092,"dur":4.197},{"text":"请注意，这里原本不是书库，而是一间纪念堂——晚唐河西都僧统洪辩的影堂。","start":8.289,"dur":7.592},{"text":"请看北壁：画着一对树。","start":15.882,"dur":2.75},{"text":"西侧树下是一位近侍女，手执杖和巾，树间挂着布囊；东侧树下是一位比丘尼，手持纨扇，树间挂着一只水壶。","start":18.632,"dur":11.868},{"text":"一把杖、一条巾、一个布囊、一把扇、一只水壶——晚唐画师的写实能力在这里不再服务于宗教叙事，它只是安静地描述了两个人如何照料另一个人。","start":30.5,"dur":14.118},{"text":"公元1900年6月22日，道士王圆箓在清理第16窟积沙时，偶然发现了这里的封门。","start":44.618,"dur":9.026},{"text":"里面堆满了四世纪到十一世纪的经卷、绢画、契约、账本和书信。","start":53.645,"dur":6.632},{"text":"有意思的是，那些被当时人视为\"废纸\"的东西——借贷契约、离婚协议、学童练字的涂鸦、寺院账本、药方和食谱——恰恰让我们第一次看见了普通唐人的生活。","start":60.276,"dur":14.895}] } },
  "mural-lotusapsara": { zh: { audio: media("tts/mural-lotusapsara/guide.zh.mp3"), cues: [{"text":"请抬头，看这口初唐的莲花飞天藻井。","start":0.05,"dur":4.082},{"text":"井心是一朵大团花，花心呈五色法轮状，花瓣顺着同一个方向旋转。","start":4.132,"dur":7.118},{"text":"花的外圈，四身持花飞天在湛蓝的天空中同向飞行，蓝云环绕。","start":11.25,"dur":6.868},{"text":"请留意她们的衣带：方向和云的流向完全一致，中心法轮的花瓣也顺着同一方向——所有元素被组织进同一个漩涡。","start":18.118,"dur":10.737},{"text":"当你站定仰望，方井一层层收拢，视线最终落进这个漩涡，然后被带着一起转。","start":28.855,"dur":7.829},{"text":"没有屏幕，没有音响，只有线条的方向和颜色的节奏。","start":36.684,"dur":5.566},{"text":"一千三百年前的画师，就已经会做沉浸式设计了。","start":42.25,"dur":4.697}] } },
  "mural-pipa": { zh: { audio: media("tts/mural-pipa/guide.zh.mp3"), cues: [{"text":"请看画面中央这位舞伎。","start":0.05,"dur":2.713},{"text":"她把琵琶甩到背后，反腕去拨，同时一足蹬地、一足踢起，身体拧成一个优美的\"三道弯\"。","start":2.763,"dur":8.605},{"text":"请特别注意她的线条：这是盛唐一路传下来的\"兰叶描\"，一根线有粗有细、有起有伏，像兰叶在风中翻转，把丝绸的飘动和身体的柔软一次画尽。","start":11.368,"dur":14.079},{"text":"再看颜色：朱砂的红、石青的蓝、石绿的绿，再加一层薄薄的金箔。","start":25.447,"dur":7.039},{"text":"一千二百年过去了，红还在烧，蓝还在亮。","start":32.487,"dur":4.382},{"text":"左右两侧不是点缀，而是一支编制完整的乐队：排箫、笙、阮、鼓、拍板，十几种乐器同时发声。","start":36.868,"dur":10.145},{"text":"这些图像是研究唐代音乐最直接的材料——很多乐器在实物上早已失传，却在这些壁画里保存了演奏的姿势、持琴的角度、手指的位置。","start":47.013,"dur":13.171},{"text":"所以有人说，敦煌壁画是一座\"会发声的博物馆\"。","start":60.184,"dur":5.066}] } },
  "mural-sahasrabhuja": { zh: { audio: media("tts/mural-sahasrabhuja/guide.zh.mp3"), cues: [{"text":"这座小窟是莫高窟保存最完好的元代洞窟，而它的全部力量来自一种几乎失传的本事：白描。","start":0.05,"dur":9.095},{"text":"请看南壁这身十一面千手千眼观音。","start":9.145,"dur":3.987},{"text":"十一张脸，自下而上按三、七、一排列，最上面是佛面。","start":13.132,"dur":6.421},{"text":"身后，一千只手一圈一圈地展开，像光轮一样托在肩后，每一只掌心里都有一只眼睛。","start":19.553,"dur":8.487},{"text":"请您放大画面——每一只手的手指，都是画师一笔一笔完整勾出来的。","start":28.039,"dur":6.211},{"text":"整铺像几乎不用重彩：脸和手用最细的淡墨，衣纹用中锋长线，身后的光轮用铁线描层层展开。","start":34.25,"dur":9.947},{"text":"没有大块颜色干扰，线的疏密本身，就成了光。","start":44.197,"dur":4.684},{"text":"这是白描与壁画在敦煌的最后一次伟大合作。","start":48.882,"dur":4.408}] } },
  "mural-threehares": { zh: { audio: media("tts/mural-threehares/guide.zh.mp3"), cues: [{"text":"请抬头看窟顶正中的藻井。","start":0.05,"dur":2.95},{"text":"三只兔子正在互相追逐，首尾相接，围成一个环。","start":3,"dur":5.461},{"text":"奇怪的是：每只兔子看起来都有两只耳朵，可整幅画上一共只画了三只耳朵——它们两两共用。","start":8.461,"dur":9.145},{"text":"这在一千五百年前是一个极高级的图形智慧，叫做\"共用形\"。","start":17.605,"dur":5.776},{"text":"更奇妙的是，同样的图案也出现在中亚的金属器、伊朗的瓷砖、欧洲中世纪教堂的彩窗上。","start":23.382,"dur":9.105},{"text":"一条丝绸之路，把这个图形从敦煌带向了整个世界。","start":32.487,"dur":5.5},{"text":"它究竟代表什么？","start":37.987,"dur":2},{"text":"三世轮回？","start":39.987,"dur":1.632},{"text":"日月运行？","start":41.618,"dur":1.632},{"text":"还是单纯的\"无穷\"？","start":43.25,"dur":2.105},{"text":"至今没有定论。","start":45.355,"dur":1.855},{"text":"再把目光移到井心四周的边框：忍冬卷草、狮子与联珠纹一圈一圈向中心收拢，每一层纹样不同，节奏却完全统一——像同一首曲子换了乐器。","start":47.211,"dur":13.763}] } },
  "mural-tigress": { zh: { audio: media("tts/mural-tigress/guide.zh.mp3"), cues: [{"text":"这是北魏壁画里最震撼的一幅，也是最难直视的一幅。","start":0.05,"dur":5.345},{"text":"摩诃萨埵太子在山中见到一只饿了七天的母虎，它已经要吃掉自己的幼崽。","start":5.395,"dur":7.184},{"text":"太子支开两位兄长，割开自己的喉咙，从崖上跳了下去。","start":12.579,"dur":5.605},{"text":"请您注意画师的构图：他没有把故事切成七格，而是把刺颈、投崖、饲虎、父母哭尸、起塔供养全部压进同一个画面——这叫\"异时同图\"。","start":18.184,"dur":13.25},{"text":"您的视线每一次移开，都会被中央那团最深的墨色拉回虎群。","start":31.434,"dur":5.895},{"text":"这就是北魏画师最了不起的地方：他们用构图代替了时间。","start":37.329,"dur":5.592}] } },
  "mural-vimalakirti": { zh: { audio: media("tts/mural-vimalakirti/guide.zh.mp3"), cues: [{"text":"请看东壁。","start":0.05,"dur":1.503},{"text":"这是《维摩诘经》最著名的一幕：居士维摩诘称病，佛陀派智慧的文殊菩萨去探病，两人展开了一场关于\"不二法门\"的大辩论。","start":1.553,"dur":11.342},{"text":"但真正让这幅画出名的，是文殊这一侧的帝王问疾图——头戴冕旒、身着大裘的帝王，身后跟着按品级排列的群臣，还有深目高鼻的各国王子。","start":12.895,"dur":13.211},{"text":"唐人把贞观年间最熟悉的朝堂仪仗，整个搬进了佛经故事。","start":26.105,"dur":5.987},{"text":"有意思的是：这些初唐杰作，直到1943年才重见天日。","start":32.092,"dur":6.289},{"text":"之前将近一千年里，它们一直被一层宋代壁画盖着。","start":38.382,"dur":5.053},{"text":"剥开表层的那一刻，等于把整个初唐画坛的最高水平，还给了世界。","start":43.434,"dur":6.421}] } },
  "mural-wutai": { zh: { audio: media("tts/mural-wutai/guide.zh.mp3"), cues: [{"text":"请看西壁。","start":0.05,"dur":1.555},{"text":"这是一张十三米长、三米六高的《五台山图》——现存最宏大的地图式山水画。","start":1.605,"dur":7.224},{"text":"五台山是文殊菩萨的道场。","start":8.829,"dur":3.066},{"text":"五代时期，敦煌到中原的路断了，但文殊信仰反而更热。","start":11.895,"dur":5.618},{"text":"曹氏家族凿了这座\"文殊堂\"，然后用整面西壁画下五台山。","start":17.513,"dur":6.053},{"text":"请靠近看：山川用俯瞰的角度，建筑却画成正立面，道路把一座座寺院、城郭、关口串起来，榜题密密麻麻写满地名。","start":23.566,"dur":12.013},{"text":"山路上有挑担的行脚僧、骑马的官员、驼着货物的商队。","start":35.579,"dur":5.684},{"text":"对于没法亲赴五台的敦煌信众，这面墙就是山本身。","start":41.263,"dur":5.447},{"text":"拿到这张画，等于拿到一份十世纪的五台山旅行手册。","start":46.711,"dur":5.184}] } },
  "mural-xiwangmu": { zh: { audio: media("tts/mural-xiwangmu/guide.zh.mp3"), cues: [{"text":"第249窟讲的不是一部经，而是一整个天空。","start":0.05,"dur":4.963},{"text":"壁面上缘，乐伎从栏墙后探出半身，吹排箫、弹琵琶、击腰鼓——栏墙与垂幔连成一条水平线，把整面墙变成天界的阳台。","start":5.013,"dur":12.829},{"text":"抬头看窟顶四披，那里是汉地神话的世界：西王母乘凤车，东王公乘龙车，阿修罗王四目四臂托着日月，雷公击鼓，飞廉奔驰，羽人朱雀往来其间。","start":17.842,"dur":15.053},{"text":"请注意一件事：佛教从印度来，却没有把这片土地原有的天空抹掉。","start":32.895,"dur":6.461},{"text":"印度来的飞天，和汉地的西王母、伏羲女娲，同住在一个穹顶之下。","start":39.355,"dur":6.605},{"text":"画师用云气把她们缝在了一起。","start":45.961,"dur":3.342},{"text":"这就是敦煌最动人的地方——它不是某一种文明的独白，而是一场持续千年的对话。","start":49.303,"dur":7.697}] } },
  "mural-zhangqian": { zh: { audio: media("tts/mural-zhangqian/guide.zh.mp3"), cues: [{"text":"请看北壁中部这一条长卷。","start":0.05,"dur":2.845},{"text":"这是敦煌独有的题材：佛教\"史迹画\"。","start":2.895,"dur":3.816},{"text":"第一景是汉武帝在甘泉宫礼拜一尊金人——传说那金人来自匈奴的祭天之所，唐人相信，这就是佛像进入中国的起点。","start":6.711,"dur":11.263},{"text":"第二景，武帝派遣张骞持节出使西域，去求取佛法。","start":17.974,"dur":5.513},{"text":"请注意这里做了什么：史实上，张骞出使在公元前二世纪，佛教传入还要再晚两百年。","start":23.487,"dur":8.803},{"text":"但初唐的画师不管这些。","start":32.289,"dur":2.882},{"text":"他们需要一条更有力的叙事：金人先来，佛法随之而至，而这条路上站着的正是敦煌。","start":35.171,"dur":8.355},{"text":"历史被重写，是为了给信仰一条来路。","start":43.526,"dur":4.224},{"text":"其余各景，是石佛浮江、金像出渚这些江南感应故事。","start":47.75,"dur":5.895},{"text":"山峦把一桩桩\"史迹\"隔成格子，人物在山水之间行走、渡河——这是敦煌壁画里最早的历史叙事，几乎就是一部初唐的连环画。","start":53.645,"dur":12.171}] } },
  "portal-intro": { zh: { audio: media("tts/welcome.zh.mp3"), cues: [{"text":"欢迎来到莫高幻境。","start":0.05,"dur":2.253},{"text":"我是九色鹿，这座数字展厅的讲解员。","start":2.303,"dur":3.947},{"text":"一千六百年前，人们把我画在莫高窟第257窟的西壁上。","start":6.25,"dur":5.961},{"text":"今天，请允许我陪您走一走这些洞窟：您可以拖动环视、双指放大细节，点一点金色的光点，听我把每幅壁画的故事讲给您。","start":12.211,"dur":11.711},{"text":"我们先从我的家——第257窟开始，好吗？","start":23.921,"dur":4.461}] } },
};
